import {validateProgrammingAnswer} from './programming-model.js';
let enginePromise;
export function previewDocument(html,css){const template=document.createElement('template');template.innerHTML=html;for(const el of template.content.querySelectorAll('script,iframe,object,embed,link,meta,base'))el.remove();for(const el of template.content.querySelectorAll('*'))for(const attr of [...el.attributes]){const key=attr.name.toLowerCase();if(key.startsWith('on')||['href','action','formaction','srcdoc','srcset','xlink:href','target','ping'].includes(key)||key==='src'&&!/^data:image\/(png|gif|jpeg|webp);base64,/i.test(attr.value))el.removeAttribute(attr.name);}return '<!doctype html><html><head><meta charset="utf-8"><meta http-equiv="Content-Security-Policy" content="default-src \'none\'; style-src \'unsafe-inline\'; img-src data:; form-action \'none\'; base-uri \'none\'"><style>'+css+'</style></head><body>'+template.innerHTML+'</body></html>';}
export async function mountProgramming(root,settings,{onDirty=()=>{}}={}){const original=root.querySelector('textarea');if(!original)throw Error('Questão de programação sem campo de resposta.');original.hidden=true;const box=document.createElement('div');box.className='programming-workspace';root.append(box);const hint=document.createElement('p');hint.className='notice';hint.textContent='Verificação estática de sintaxe: não executa Python ou C#, não verifica bibliotecas/Unity e não atribui nota automaticamente. Resultados são orientativos; a correção é feita pela rubrica.';box.append(hint);const files=settings.language==='htmlcss'?[['html','HTML',settings.starterHtml],['css','CSS',settings.starterCss]]:[[settings.language,settings.language==='python'?'Python':'C#',settings.starterCode]],editors=[],panels=[],tabs=document.createElement('div');tabs.className='actions';box.append(tabs);let active=0,disposed=false,timer,revision=0;
 const report=document.createElement('div');report.className='programming-report';report.setAttribute('aria-live','polite');
 const sync=()=>{original.value=settings.language==='htmlcss'?JSON.stringify({html:editors[0]?.getValue()||'',css:editors[1]?.getValue()||''}):editors[0]?.getValue()||'';onDirty();};
 for(const [i,[language,label,starter]]of files.entries()){const tab=document.createElement('button');tab.type='button';tab.textContent=label;tabs.append(tab);const panel=document.createElement('div');panel.hidden=i!==0;panel.className='programming-file';box.append(panel);panels.push(panel);const fallback=document.createElement('textarea');fallback.value=starter;fallback.spellcheck=false;fallback.maxLength=20000;fallback.className='code-input';fallback.setAttribute('aria-label','Código '+label);panel.append(fallback);editors.push({getValue:()=>fallback.value,destroy(){}});fallback.oninput=()=>{revision++;sync();queue();};tab.onclick=()=>{active=i;panels.forEach((p,n)=>p.hidden=n!==i);[...tabs.children].forEach((b,n)=>b.setAttribute('aria-pressed',String(n===i)));};tab.setAttribute('aria-pressed',String(i===0));}
 const controls=document.createElement('div');controls.className='actions';box.append(controls);const check=document.createElement('button');check.type='button';check.textContent='Verificar sintaxe';check.hidden=settings.validation==='off';controls.append(check);box.append(report);let engine;
 async function validate(){if(settings.validation==='off'||disposed)return;const turn=++revision;report.replaceChildren();if(!engine){report.textContent='Validador indisponível. Sua resposta pode ser enviada para correção do professor.';return;}try{const items=[];for(let i=0;i<files.length;i++){const code=editors[i].getValue();items.push(...engine.analyze(files[i][0],code).map(issue=>({...issue,file:files[i][1]})));}if(disposed||turn!==revision)return;const label=document.createElement('p');label.textContent=items.length?'Pontos para revisar (orientações do analisador):':'Nenhum problema identificado pelas regras disponíveis. Isso não garante que o programa esteja correto.';report.append(label);const list=document.createElement('ul');for(const item of items){const li=document.createElement('li');li.textContent=`${item.file} · linha ${item.line}, coluna ${item.column}: ${item.message}`;list.append(li);}report.append(list);}catch(e){report.textContent=e.message||'Falha na verificação. A entrega continua disponível.';}}
 function queue(){clearTimeout(timer);if(settings.validation==='live')timer=setTimeout(validate,700);}
 check.onclick=validate;
 if(settings.preview&&settings.language==='htmlcss'){const button=document.createElement('button');button.type='button';button.textContent='Visualizar página';controls.append(button);const frame=document.createElement('iframe');frame.title='Prévia isolada de HTML e CSS';frame.setAttribute('sandbox','');frame.referrerPolicy='no-referrer';frame.className='programming-preview';frame.hidden=true;box.append(frame);button.onclick=()=>{if(editors.some(e=>e.getValue().length>20000)){report.textContent='Reduza o código para até 20.000 caracteres por arquivo.';return;}frame.srcdoc=previewDocument(editors[0].getValue(),editors[1].getValue());frame.hidden=false;};}
 try{enginePromise??=import('./vendor/programming-engine.js');engine=await enginePromise;if(!disposed)for(let i=0;i<files.length;i++){const panel=panels[i],value=editors[i].getValue();panel.replaceChildren();editors[i]=engine.mountEditor(panel,{language:files[i][0],code:value,complete:settings.autocomplete,onChange:()=>{revision++;sync();queue();}});}}catch{report.textContent='Editor avançado indisponível. Use o campo de código; a validação será feita pelo professor.';}
 original.value=settings.language==='htmlcss'?JSON.stringify({html:editors[0].getValue(),css:editors[1].getValue()}):editors[0].getValue();
 return {read(){return validateProgrammingAnswer(settings.language,settings.language==='htmlcss'?{html:editors[0].getValue(),css:editors[1].getValue()}:editors[0].getValue());},destroy(){disposed=true;clearTimeout(timer);editors.forEach(e=>e.destroy());box.remove();}};
}
